import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { CliNotFoundError } from '../packageManagers/execUtils';
import { alignCargoLock, syncCargoLocks } from './versionLockSync';

const LOCK = [
  '# This file is automatically @generated by Cargo.',
  'version = 4',
  '',
  '[[package]]',
  'name = "app-core"',
  'version = "4.0.0"',
  'dependencies = [',
  ' "app-protocol",',
  ' "serde",',
  ']',
  '',
  '[[package]]',
  'name = "app-protocol"',
  'version = "4.0.0"',
  '',
  '[[package]]',
  'name = "serde"',
  'version = "4.0.0"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"',
  'checksum = "abc"',
  '',
].join('\r\n');

describe('alignCargoLock', () => {
  it('moves the workspace crates to their new versions and nothing else', () => {
    const next = alignCargoLock(
      LOCK,
      new Map([
        ['app-core', '4.1.0'],
        ['app-protocol', '4.1.0'],
        ['serde', '4.1.0'],
      ]),
    );

    expect(next).toBe(
      LOCK.replace('"app-core"\r\nversion = "4.0.0"', '"app-core"\r\nversion = "4.1.0"').replace(
        '"app-protocol"\r\nversion = "4.0.0"',
        '"app-protocol"\r\nversion = "4.1.0"',
      ),
    );
    // A registry crate sharing a name with a member keeps its locked version.
    expect(next).toContain('name = "serde"\r\nversion = "4.0.0"');
  });

  it('returns the very same text when the lock already matches', () => {
    expect(alignCargoLock(LOCK, new Map([['app-core', '4.0.0']]))).toBe(LOCK);
  });
});

describe('syncCargoLocks', () => {
  let root: string;

  function setUp(): void {
    root = mkdtempSync(join(tmpdir(), 'runova-lock-sync-'));
    mkdirSync(join(root, 'apps', 'core', 'crates', 'protocol'), { recursive: true });
    writeFileSync(join(root, 'apps', 'core', 'Cargo.toml'), '[workspace]\n');
    writeFileSync(join(root, 'apps', 'core', 'Cargo.lock'), LOCK);
  }

  afterEach(() => {
    if (root) rmSync(root, { recursive: true, force: true });
  });

  it('rewrites the lock above a changed Cargo.toml, read once per workspace', async () => {
    setUp();
    const readCrates = vi.fn(
      async () =>
        new Map([
          ['app-core', '4.1.0'],
          ['app-protocol', '4.1.0'],
        ]),
    );

    const result = await syncCargoLocks(
      root,
      ['apps/core/Cargo.toml', 'apps/core/crates/protocol/Cargo.toml', 'package.json'],
      readCrates,
    );

    expect(result).toEqual({ updated: ['apps/core/Cargo.lock'], warnings: [] });
    expect(readCrates).toHaveBeenCalledTimes(1);
    expect(readCrates).toHaveBeenCalledWith(join(root, 'apps', 'core'));
    const lock = readFileSync(join(root, 'apps', 'core', 'Cargo.lock'), 'utf-8');
    expect(lock).toContain('name = "app-core"\r\nversion = "4.1.0"');
    expect(lock).toContain('name = "app-protocol"\r\nversion = "4.1.0"');
  });

  it('leaves locks alone when no Cargo.toml changed', async () => {
    setUp();
    const readCrates = vi.fn();

    const result = await syncCargoLocks(root, ['package.json'], readCrates);

    expect(result).toEqual({ updated: [], warnings: [] });
    expect(readCrates).not.toHaveBeenCalled();
  });

  it('says how to fix the lock by hand when cargo is missing', async () => {
    setUp();

    const result = await syncCargoLocks(root, ['apps/core/Cargo.toml'], async () => {
      throw new CliNotFoundError('cargo is not available on PATH');
    });

    expect(result.updated).toEqual([]);
    expect(result.warnings).toEqual([
      'apps/core/Cargo.lock was not updated because cargo is not on PATH. Run `cargo update --workspace --offline` in apps/core before committing, or builds with --locked will fail.',
    ]);
    expect(readFileSync(join(root, 'apps', 'core', 'Cargo.lock'), 'utf-8')).toBe(LOCK);
  });
});
